import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BuUvxvtQ.js";const h=JSON.parse('{"title":"Account & Support","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/account-and-support.md","filePath":"web-app/account-and-support.md"}'),n={name:"web-app/account-and-support.md"};function s(i,e,d,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="account-support" tabindex="-1">Account &amp; Support <a class="header-anchor" href="#account-support" aria-label="Permalink to &quot;Account &amp; Support&quot;">​</a></h1><h2 id="account-page" tabindex="-1">Account page <a class="header-anchor" href="#account-page" aria-label="Permalink to &quot;Account page&quot;">​</a></h2><p>The <strong>Account</strong> page (<code>/account</code>) is the hub for your profile and safety controls. It shows:</p><ul><li>Your <strong>plan badge</strong> — Free, Pro, or Dev.</li><li><strong>AI usage today</strong> against your daily limits.</li><li><strong>Credits</strong> balances (Pro/Dev only), via the Credit Center.</li><li>Embedded <strong><a href="./security-and-privacy.html#security-page">Security</a></strong> and <strong><a href="./security-and-privacy.html#privacy-hub">Privacy Hub</a></strong> sections.</li></ul><p>Use it as the entry point for security settings, privacy controls, and API access.</p><h3 id="credit-center" tabindex="-1">Credit Center <a class="header-anchor" href="#credit-center" aria-label="Permalink to &quot;Credit Center&quot;">​</a></h3><p>The Credit Center (embedded in the Account page for Pro/Dev users) shows your three balances and lets you allocate <code>$1.00 → 50 API Credit</code> to a chosen key. See <a href="./api-dashboard.html#credits">API Dashboard → Credits</a> for the full breakdown.</p><h2 id="plans" tabindex="-1">Plans <a class="header-anchor" href="#plans" aria-label="Permalink to &quot;Plans {#plans}&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Free</th><th>Pro</th></tr></thead><tbody><tr><td>Price</td><td>A$0</td><td>A$4/month</td></tr><tr><td>AI uses</td><td>20/day</td><td>50 App Credits/day</td></tr><tr><td>Follow-ups</td><td>40/day</td><td>400/day</td></tr><tr><td>Closet</td><td>4 uses/day</td><td>Unlimited</td></tr><tr><td>Source picker</td><td>4/day</td><td>Unlimited</td></tr><tr><td>BYOK AI key</td><td>—</td><td>✅</td></tr><tr><td>Custom prompts</td><td>—</td><td>✅</td></tr><tr><td>Active API keys</td><td>3</td><td>20</td></tr></tbody></table><ul><li>The <strong>Dev</strong> tier bypasses all limits and is only provisioned to developer accounts.</li><li>The <strong>Demo</strong> tier is created automatically in preview/development environments and multiplies the free limits by 10 for testing.</li></ul><p>A &quot;Pay as you go&quot; plan for flexible App Credit purchases is planned but not live yet.</p><h2 id="live-demo" tabindex="-1">Live Demo <a class="header-anchor" href="#live-demo" aria-label="Permalink to &quot;Live Demo {#live-demo}&quot;">​</a></h2><p>The landing page at <a href="https://skystyle.app/#demo" target="_blank" rel="noreferrer">skystyle.app/#demo</a> offers a <strong>no-login live demo</strong>: pick a location and see real weather data (no AI recommendation in the demo). It&#39;s a quick way to evaluate Sky Style before creating an account.</p><h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback {#feedback}&quot;">​</a></h2><p>The <strong>Feedback</strong> page (<code>/feedback</code>) lets signed-in users share a bug report, suggestion, or message:</p><ul><li>Pro and Dev context is passed along automatically.</li><li>Your past submissions are tracked as <strong>tickets</strong> you can review on the same page.</li><li>Every message is read personally.</li></ul><p>You must be signed in to send feedback.</p><h2 id="inbox" tabindex="-1">Inbox <a class="header-anchor" href="#inbox" aria-label="Permalink to &quot;Inbox {#inbox}&quot;">​</a></h2><p>The <strong>Inbox</strong> keeps recommendation, support, system, and changelog notices together in one place:</p><ul><li>Automatic recommendation results are delivered here.</li><li>Unread counts surface across the app.</li><li>Notices are categorised (recommendation, support, system, changelog).</li></ul><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog {#changelog}&quot;">​</a></h2><p>The <strong>Changelog</strong> page (<code>/changelog</code>) lists every published release. Entries can include:</p><ul><li>A version number, title, and short description.</li><li>Extended Markdown content with inline images.</li><li>A category and type (update or post).</li><li>A call-to-action button linking to more detail.</li><li>A &quot;large&quot; modal view for richer posts.</li></ul><p>New entries can surface on your next login; the <a href="./settings.html">Settings</a> page also shows a preview of recent changes.</p><h2 id="help-and-service-status" tabindex="-1">Help and service status <a class="header-anchor" href="#help-and-service-status" aria-label="Permalink to &quot;Help and service status {#help-and-service-status}&quot;">​</a></h2><p>Use the app <strong><a href="#inbox">Inbox</a></strong> or <strong><a href="#feedback">Feedback</a></strong> page for account help. API users should consult the <a href="./../api/errors.html">API error guide</a> and the <a href="https://status.coolmanyt.com/" target="_blank" rel="noreferrer">COOLman service status page</a> for service and downtime information.</p><p>Monitoring integrations can use the status page&#39;s <a href="https://status.coolmanyt.com/v3/components.json" target="_blank" rel="noreferrer">live component status JSON</a>.</p>',27)])])}const g=t(n,[["render",s]]);export{h as __pageData,g as default};
